function doSeedProducts() {
    const collection = $app.dao().findCollectionByNameOrId("products");
    let count = 0;

    for (let i = 0; i < SEED_PRODUCTS.length; i++) {
        const item = SEED_PRODUCTS[i];
        try {
            let record = null;
            try {
                record = $app.dao().findRecordById("products", item.id);
            } catch(e) {
                record = new Record(collection, { id: item.id });
            }

            record.set("name", item.name);
            record.set("description", item.description);
            record.set("image", item.image);
            record.set("images", item.images);
            record.set("category", item.category);
            record.set("viralTags", item.viralTags);
            record.set("retailers", item.retailers);

            $app.dao().saveRecord(record);
            count++;
        } catch(err) {
            // Ignore duplicate errors
        }
    }
    return count;
}

onAfterBootstrap((e) => {
    try {
        const records = $app.dao().findRecordsByExpr("products", $dbx.exp("1=1"));
        if (records.length < 50) {
            console.log(">> Auto seeding makeup catalog products via onAfterBootstrap hook...");
            const seeded = doSeedProducts();
            console.log(">> Successfully auto-seeded " + seeded + " products.");
        }
    } catch(err) {
        console.log("Hook bootstrap error: " + err);
    }
});

routerAdd("GET", "/api/auto-seed-products", (e) => {
    try {
        const seeded = doSeedProducts();
        return e.json(200, { message: "Successfully seeded products!", count: seeded });
    } catch(err) {
        return e.json(500, { error: String(err) });
    }
});
